      "raw_content": "카페홈\n좌담회/설문/주부알바\n가입\n검색\n메뉴\n▶좌담회 신청하기(당일 현금지급)\n앱 열기\n▶8/11] 올리브영 스킨케어 사용자 좌담회 / 만 24세 ~ 49세 여성(대학생 제외)\n본문 기타 기능\n하늘\n카페매니저\n채팅\n작성일\n2026.07.28. 22:47\n조회 31\n▶8/11] 올리브영 스킨케어 사용자 좌담회 / 만 24세 ~ 49세 여성(대학생 제외)\n=============================================\n※ 사전 통화후에 관련 제품 사진 전송\n* 공통조건\n- 올리브영에서 스킨케어 자주 구매하여 사용하는 분\n- 정기적으로 피부과 시술 받는 분\n- 올리브영 방문후 사전과제 작성에 동의하는 분\n- 방문 좌담회로 진행되므로 내방에 문제가 없는 분\n-------------------------------------------------------------------\n◈일정 : 8월 11일(화) 10시 30분 / 1시 30분 / 4시\n◈하루1타임 2시간내외====>사 례 비(당일지급) :6 만원(사전과제 비용 포함)\n◈위 치 : 강남구청역 부근(전화 인터뷰후 참석 확정되신 분에 한하여 문자로 알려드립니다)\n-------------------------------------------------------------------\n▶기재 사항\n*신청시 기재 사항 : 최대한 자세히 기재해 주세요(브랜드/모델명) / 제품사진제출\n1. 이름/ 성별/ 나이(주민번호앞자리)/ 거주구/ 연락처/ 직업( 직장명&부서명)/결혼 여부\n2. 현재 사용중인 스킨케어 브랜드 모두(미스트부터~~썬크림까지),\n3, 현재 사용중인 뷰티 디바이스기기 있는분 제품명\n4. 월 평균 올리브영 방문 횟수& 올리브영에서(오프라인+온라인) 구입한 스킨케어 구입 가격\n5. 최근 1년내 받아본 피부과 시술명\n-\n[아래 URL에 (클릭!!)하여 신청해 주세요].(스마트폰도 가능!!)]\nhttps://forms.gle/rQDTx1G5iedXe8fA8\n좋아요\n0\n'좋아요'로 마음을 나누세요!\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n지금 가입하고 댓글에 참여해보세요!\n전체글\n▶8/11] 올리브영 스킨케어 사용자 좌담회 / 만 24세 ~ 49세 여성(대학생 제외)\n하늘\n26.07.28.\n댓글\n0\n▶8/5~6] 홍삼 관련 좌담회 / 만35-64세 남녀\n하늘\n26.07.28.\n댓글\n0\n▶8/1~3 ]한방의료 관련 좌담회 /만 20-69세 남녀\n하늘\n26.07.28.\n댓글\n0\n▶8/10~8/12 진행]8월1차 담배 맛 평가 설문조사 참여자 모집/ 만20-49세 남자\n하늘\n26.07.28.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그인전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
