      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n50~57세 미혼남성) 2시간 20만) 조기퇴직의 원인 파악 좌담회 (조기퇴직 경험자)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.07.28. 10:14\n조회 4\n구독\n50~57세 남성) 2시간 20만) 조기퇴직의 원인 파악 좌담회 (조기퇴직 경험자)\n신청하신분은 재신청 안하셔도 됩니다\n▶참석 대상 : 남성 조기 퇴직 경험자\n세부조건 – 50~57세 나이에 종사자 규모 30인 이상인 민간기업에 다니다가 퇴사(퇴직)한 경험자\n▶소요 시간 : 약 2시간 정도 소요 예정\n▶일시 : 개인별 통화 후 일정 조율\n▶조사방법 : 대면\n▶참석사례비 : 20만원(세전)\n조기퇴직의 원인 파악을 위한 FGI 대상자 선정 질문지(조기퇴직 경험자)\nQ1. 귀하의 성별은 무엇입니까?\n① 남성 ② 여성 ☞ 중단\nQ2. 귀하의 현재 나이는 만으로 몇 세입니까? ( )세 ☞ 만 50~64세 진행\nQ3. 귀하는 만 50~59세 나이에 다니던 직장에서 퇴사(퇴직)한 경험이 있습니까?\n① 예 / 있음 ② 아니오 / 없음 ☞ 중단\nQ3-1. 퇴사(퇴직) 당시 나이는 몇 살이었습니까? ( )세 ☞ 만 50~59세 진행\nQ3-2. 퇴사(퇴직) 당시 고용형태는 정규직이었습니까?\n① 예 / 정규직 ② 아니오 / 비정규직 ☞ 중단\nQ3-3. 퇴직 사유는 다음 중 어디에 해당됩니까?\n① 명예 희망퇴직 ② 권고사직 ③ 정리해고\n④ 본인 의지에 의한 자발적 이직(퇴사) ⑤ 기타 ( )\n☞ ‘정년퇴직’, ‘하던 사업(자영업 포함)을 그만 두었다’ 등의 사유가 응답되면 중단\nQ4. 퇴직한 회사의 유형은 다음 중 무엇입니까?\n① 민간기업 (외국계 회사 포함)\n② 정부, 지방자치단체, 경찰서 등 국가기관 ☞ 중단\n③ 정부(지방자치단체) 산하기관 또는 출연기관(공기업, 공공기관 등 포함) ☞ 중단\n④ 민간 협회·단체\nQ5. 퇴직한 회사의 종사자 규모는 몇명 정도 였습니까?\n① 29인 이하 ☞ 중단\n② 30~49인\n③ 50~99인\n④ 100~199인\n⑤ 200~299인\n⑥ 300~499인\n⑦ 500인 이상\nQ6. 퇴직한 회사의 주 업종은 무엇이었습니까?\n① 제조업 ② 비제조업 (구체적으로 : ______________ )\nhttps://forms.gle/qzxj67guAxtnB7AV9\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.07.28. 10:24 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n50~57세 기혼남성) 2시간 20만) 조기퇴직의 원인 파악 좌담회 (조기퇴직 경험자)\n좌담회알바좌담회카페\n26.07.28.\n댓글\n2\n50~57세 미혼남성) 2시간 20만) 조기퇴직의 원인 파악 좌담회 (조기퇴직 경험자)\n좌담회알바좌담회카페\n26.07.28.\n댓글\n1\n8/5~6) 60-64세 남성 ) 홍삼 관련좌담회\n좌담회알바좌담회카페\n26.07.28.\n댓글\n2\n8/5~6) 60-64세 여성 ) 홍삼 관련좌담회\n좌담회알바좌담회카페\n26.07.28.\n댓글\n2\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
