      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n7/31) 20~50세) 온라인 쇼핑 관련 조사-3그룹 국내 생산 위주 제뭎 구매자 해외 및 마카오제품 관심도는 낮으나 구매 거부감 없는자\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.07.28. 11:24\n조회 95\n구독\n7/31) 20~50세) 온라인 쇼핑 관련 조사-3그룹 국내 생산 위주 제뭎 구매자 해외 및 마카오제품 관심도는 낮으나 구매 거부감 없는자\n신청하신분은 재신청 안하셔도 됩니다\n공통 조건 20~50세 세후 가구 소득 6100만원 이상\n• 활발한 온라인 쇼핑 이용자 (아래 중 1개 이상 충족):\no 온라인 쇼핑을 인지하고 관심을 가지고 있으며, 온라인 소비에 대해 긍정적인 태도를 가짐.\no 전자상거래 플랫폼 (국내 전자상거래, 해외 직구 및 소셜 커머스 포함)을 정기적으로 둘러보는 습관이 있음.\no 국내 또는 해외 전자상거래 이용 경험이 있음 (구매 빈도 및 품목과 관계 없이 온라인 구매를 최소 1회 완료)\n• 활발한 소셜미디어 사용자 (다음 중 1개 이상 충족):\no 최소 주 3일 이상 소셜 미디어 사용\no 하루 평균 소셜 미디어 30분 이상 이용\no 최근 1개월 이내에 소셜 미디어 광고, KOL (인플루언서) 추천 또는 라이브 커머스 판매 컨텐츠 시청 또는 클릭한 경험이 있음\no 신제품 또는 브랜드 정보를 알아보거나 상품 구매 시 참고를 위해 소셜 미디어 이용\n• 다음 중 최소 1개 이상의 마카오 생산 수입 소비재를 접한 경험이 있음\no 식품\no 건강기능식품\no 의약품\no 문화/창작 상품\no 주얼리\n마카오 관광 및 마카오 생산 상품에 거부감이 없음\n좌담회 참여 의향이 있으며, 모든 참여 조건을 충족\n3그룹 국내 생산 위주 제뭎 구매자 해외 및 마카오제품 관심도는 낮으나 구매 거부감 없는자\n7월 31일 좌담회 가능자 9시30 ~11:30 12시30~2시반 3시~5시 그룹별 시간 조율 필요함(참여 희망자 중\n참여 가능한 사람의 그룹이 많은 사람 위주로 시간 편성 예정)\n참석자 사례비 : 6만원\nhttps://forms.gle/ALSMNi6yPEmN5tah9\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.07.28. 13:04 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n8/11) 만 24세 ~29세 여성(대학생 제외) 올리브영 스킨케어 사용자 좌담회\n좌담회알바좌담회카페\n26.07.28.\n댓글\n1\n7/31) 20~50세) 온라인 쇼핑 관련 조사-3그룹 국내 생산 위주 제뭎 구매자 해외 및 마카오제품 관심도는 낮으나 구매 거부감 없는자\n좌담회알바좌담회카페\n26.07.28.\n댓글\n1\n고유링크) 급급급) 만18세 이상 모든 연령대 여성 (아이폰 사용자만 가능) 생성형 AI 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.07.28.\n댓글\n2\n고유링크) 급급급) 만18세 이상 모든 연령대 남성 (아이폰 사용자만 가능) 생성형 AI 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.07.28.\n댓글\n2\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
